import csv

rows = []
with open('contacts.csv', newline='') as f:
    reader = csv.DictReader(f)
    for i, row in enumerate(reader):
        email = row['email'].strip().lower()
        rows.append((row['name'], email, row['created'], i))

best = {}
for name, email, created, i in rows:
    if email not in best:
        best[email] = (name, email, created, i)
    else:
        cur = best[email]
        if (created, i) < (cur[2], cur[3]):
            best[email] = (name, email, created, i)

out = sorted(best.values(), key=lambda r: (r[2], r[1]))
with open('clean.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['name', 'email', 'created'])
    for name, email, created, i in out:
        w.writerow([name, email, created])

print(len(out))
